INSERT INTO "resources" (id, title, category, body, state, city, phone, url, address, hours, free, income_limit, languages, priority, type, verified, name, description, website, email, eligibility, updated_at) VALUES
  (1,'988 Suicide & Crisis Lifeline','CRISIS_LINE','Free, confidential support 24/7. Call or text 988. Also available via chat at 988lifeline.org. Connects you with a trained crisis counselor. Available in Spanish: press 2.',NULL,NULL,'988','https://988lifeline.org',NULL,'24/7',1,NULL,'["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (2,'National Domestic Violence Hotline','CRISIS_LINE','Free, confidential support for domestic violence survivors 24/7. Call 1-800-799-7233 or text START to 88788. Live chat available at thehotline.org. TTY: 1-800-787-3224. Assistance in 200+ languages.',NULL,NULL,'1-800-799-7233','https://thehotline.org',NULL,'24/7',1,NULL,'["English", "Spanish", "200+ languages"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (3,'SAMHSA National Helpline','CRISIS_LINE','Substance Abuse and Mental Health Services Administration. Free, confidential, 24/7 treatment referral and information service for individuals facing mental health or substance use disorders. Call 1-800-662-4357. Text your ZIP to 435748 to find local treatment.',NULL,NULL,'1-800-662-4357','https://www.samhsa.gov/find-help/national-helpline',NULL,'24/7',1,NULL,'["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (4,'National Sexual Assault Hotline (RAINN)','CRISIS_LINE','Free, confidential support for sexual assault survivors 24/7. Call 1-800-656-4673 or use the online hotline at rainn.org/get-help. Connects you with a local sexual assault service provider.',NULL,NULL,'1-800-656-4673','https://www.rainn.org',NULL,'24/7',1,NULL,'["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (5,'Crisis Text Line','CRISIS_LINE','Free, 24/7 mental health crisis support via text. Text HOME to 741741 from anywhere in the USA. Trained crisis counselors respond within minutes.',NULL,NULL,'Text HOME to 741741','https://www.crisistextline.org',NULL,'24/7',1,NULL,'["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (6,'Veterans Crisis Line','CRISIS_LINE','Free, confidential crisis support for veterans, service members, and their families. Call 988 and press 1, text 838255, or chat online. Responders are trained in military culture and VA benefits.',NULL,NULL,'988 then press 1','https://www.veteranscrisisline.net',NULL,'24/7',1,NULL,'["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (7,'National Alliance for Eating Disorders Helpline','CRISIS_LINE','Free referral and support helpline for eating disorders. Call 1-866-662-1235. Available Monday–Friday 9am–7pm ET. Note: NEDA helpline is permanently discontinued; use NAED instead.',NULL,NULL,'1-866-662-1235','https://www.allianceforeatingdisorders.com',NULL,'Mon-Fri 9am-7pm ET',1,NULL,'["English"]',2,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (8,'National Child Abuse Hotline','CRISIS_LINE','Free, 24/7 crisis intervention and support for child abuse situations. Call 1-800-422-4453 (1-800-4-A-CHILD). Available in 140 languages via interpreter services.',NULL,NULL,'1-800-422-4453','https://www.childhelp.org',NULL,'24/7',1,NULL,'["English", "140+ languages"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (9,'Legal Services Corporation (LSC)','LEGAL_AID','Federally funded nonprofit providing free civil legal aid to low-income Americans. Funds 132 independent legal aid organizations covering every US county. Find your local program at lsc.gov/find-legal-aid. Income limit: generally 125% of federal poverty level.',NULL,NULL,'202-295-1500','https://www.lsc.gov/find-legal-aid','3333 K St NW, Washington DC 20007',NULL,1,'125% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (10,'Law Help (LawHelp.org)','LEGAL_AID','Free legal information and referrals by state. Find legal aid, self-help resources, and court forms for your state. Available in multiple languages. Covers: housing, benefits, family law, criminal record clearing.',NULL,NULL,NULL,'https://www.lawhelp.org',NULL,NULL,1,NULL,'["English", "Spanish", "Multiple"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (11,'American Bar Foundation Pro Bono Resources','LEGAL_AID','The ABA provides a directory of free legal help resources. Visit americanbar.org/groups/legal_services/flh-home for a lawyer referral. Many local bar associations offer free 30-minute consultations.',NULL,NULL,'312-988-5000','https://www.americanbar.org/groups/legal_services/flh-home',NULL,NULL,1,NULL,'["English"]',2,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (12,'Innocence Project','LEGAL_AID','Free legal representation for people who may have been wrongfully convicted. Specializes in DNA evidence cases. Based in New York. Submit a case at innocenceproject.org/get-help/.',NULL,'New York, NY','212-364-5340','https://innocenceproject.org','40 Worth St, New York NY 10013',NULL,1,NULL,'["English"]',2,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (13,'ACLU (American Civil Liberties Union)','LEGAL_AID','Nonprofit defending civil rights and civil liberties. Provides free legal representation in cases involving constitutional rights violations. Find your state ACLU chapter at aclu.org. Cases must involve civil liberties issues — not all criminal cases qualify.',NULL,NULL,'212-549-2500','https://www.aclu.org','125 Broad St, New York NY 10004',NULL,1,NULL,'["English"]',2,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (14,'National Immigrant Justice Center','LEGAL_AID','Free and low-cost legal representation for immigrants, refugees, and asylum seekers. Particularly strong in removal defense and DACA. Call 312-660-1370 or visit immigrantjustice.org.',NULL,'Chicago, IL','312-660-1370','https://immigrantjustice.org','224 S Michigan Ave, Chicago IL 60604',NULL,1,'Low income','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (15,'Drug Policy Alliance','LEGAL_AID','Advocates for drug policy reform and provides Know Your Rights resources. Free guides on what to do if arrested for drugs. Visit drugpolicy.org/resource for state-by-state guidance.',NULL,NULL,'212-613-8020','https://drugpolicy.org',NULL,NULL,1,NULL,'["English", "Spanish"]',2,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (16,'Legal Aid Society of Middle Tennessee','LEGAL_AID','Free civil legal services for low-income residents of Middle Tennessee. Counties served: Davidson, Williamson, Wilson, Rutherford, and 40+ others. Call 615-244-6610. Walk-in hours vary by office.','TN','Nashville, TN','615-244-6610','https://www.las.org','300 Deaderick St, Nashville TN 37201','Mon-Fri 8:30am-4:30pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (17,'Memphis Area Legal Services','LEGAL_AID','Free civil legal aid for Shelby County residents below 200% federal poverty level. Services: housing, domestic violence, benefits, consumer issues. Call 901-523-8822.','TN','Memphis, TN','901-523-8822','https://www.malsi.org','44 N 2nd St Ste 400, Memphis TN 38103','Mon-Fri 9am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (18,'East Tennessee Legal Services','LEGAL_AID','Free legal services for low-income residents of East Tennessee. Covers: Knox, Anderson, Blount, and surrounding counties. Call 865-637-0484.','TN','Knoxville, TN','865-637-0484','https://www.etls.org','502 Gay St Ste 404, Knoxville TN 37902','Mon-Fri 8:30am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (19,'Lone Star Legal Aid','LEGAL_AID','Largest legal aid provider in Texas. Covers 72 counties in East Texas, the Gulf Coast region, and Greater Houston area. Call 1-800-733-8394 or visit lonestarlegal.org.','TX','Houston, TX','1-800-733-8394','https://lonestarlegal.org','1415 Fannin St, Houston TX 77002','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (20,'Dallas Volunteer Attorney Program','LEGAL_AID','Free civil legal services for low-income Dallas County residents. Partners with 6,000+ volunteer attorneys. Call 214-243-2243 for intake.','TX','Dallas, TX','214-243-2243','https://www.dvap.org','1515 Main St, Dallas TX 75201','Mon-Fri 8:30am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (21,'Texas RioGrande Legal Aid','LEGAL_AID','Free legal services across South and West Texas including San Antonio, El Paso, Laredo, and the Rio Grande Valley. Call 956-996-8752. Bilingual staff.','TX','San Antonio, TX','956-996-8752','https://www.trla.org','4920 N IH-35, Austin TX 78751','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (22,'Legal Aid Society of the Orange County Bar','LEGAL_AID','Free civil legal services for Orange County (Orlando) residents. Income-eligible individuals call 407-841-8310.','FL','Orlando, FL','407-841-8310','https://www.legalaidocba.org','100 E Robinson St, Orlando FL 32801','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (23,'Three Rivers Legal Services','LEGAL_AID','Free legal aid for 18 North Florida counties including Gainesville and Tallahassee area. Call 352-372-0519.','FL','Gainesville, FL','352-372-0519','https://www.trls.org','901 NW 8th Ave Ste D4, Gainesville FL 32601','Mon-Fri 8:30am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (24,'Bay Area Legal Aid','LEGAL_AID','Free legal services for low-income residents of the San Francisco Bay Area. Covers: San Francisco, Alameda, Contra Costa, Marin, and Napa counties. Call 415-982-1300.','CA','San Francisco, CA','415-982-1300','https://baylegal.org','1735 Telegraph Ave, Oakland CA 94612','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (25,'Inland Counties Legal Services','LEGAL_AID','Free legal services for low-income residents of Riverside, San Bernardino, and Imperial counties. Call 888-245-4257.','CA','Riverside, CA','888-245-4257','https://www.inlandcountylegalservices.org','1737 Atlanta Ave Ste H4, Riverside CA 92507','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (26,'Greater Los Angeles Legal Aid Foundation','LEGAL_AID','Free civil legal services for LA County residents. One of the largest legal aid programs in the US. Call 213-640-3881.','CA','Los Angeles, CA','213-640-3881','https://lafla.org','530 S Virgil Ave, Los Angeles CA 90020','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (27,'Legal Aid Society of New York','LEGAL_AID','Nation''s oldest and largest nonprofit legal services provider. Provides criminal defense, civil, and juvenile justice services in NYC. Call 212-577-3300 for information.','NY','New York City, NY','212-577-3300','https://legalaidnyc.org','40 Worth St, New York NY 10013','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish", "Multiple"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (28,'Prairie State Legal Services','LEGAL_AID','Free civil legal services for low-income residents of northern and central Illinois (outside of Cook County). Covers 36 counties. Call 800-342-5756.','IL','Rockford, IL','800-342-5756','https://www.pslegal.org','1975 Springfield Ave, Rockford IL 61108','Mon-Fri 8:30am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (29,'Land of Lincoln Legal Aid','LEGAL_AID','Free civil legal services for low-income residents of central and southern Illinois. Covers 65 counties. Call 800-252-8629.','IL','Springfield, IL','800-252-8629','https://www.lincolnlegal.org','1020 S Spring St, Springfield IL 62704','Mon-Fri 8:30am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (30,'Legal Aid Society of Cleveland','LEGAL_AID','Free legal services for low-income residents of Cuyahoga, Ashtabula, Geauga, Lake, and Lorain counties. Call 216-687-1900.','OH','Cleveland, OH','216-687-1900','https://lasclev.org','1223 W 6th St, Cleveland OH 44113','Mon-Fri 9am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (31,'Legal Aid of Western Ohio','LEGAL_AID','Free civil legal services for 32 counties in western Ohio. Call 888-534-1432.','OH','Dayton, OH','888-534-1432','https://lawolaw.org','40 N Perry St, Dayton OH 45402','Mon-Fri 8:30am-5pm',1,'200% FPL','["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (32,'Atlanta Legal Aid Society','LEGAL_AID','Free civil legal services for low-income residents of metro Atlanta. Covers: Fulton, DeKalb, Cobb, Clayton, and Gwinnett counties. Call 404-524-5811.','GA','Atlanta, GA','404-524-5811','https://atlantalegalaid.org','151 Spring St NW, Atlanta GA 30303','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (33,'Legal Aid of North Carolina','LEGAL_AID','Free civil legal services for low-income North Carolinians statewide. Call 866-219-5262 (statewide intake line).','NC',NULL,'866-219-5262','https://legalaidnc.org',NULL,'Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (34,'Philadelphia Legal Assistance','LEGAL_AID','Free legal services for low-income Philadelphia residents. Call 215-981-3800.','PA','Philadelphia, PA','215-981-3800','https://philalegal.org','718 Arch St Ste 300N, Philadelphia PA 19106','Mon-Fri 9am-5pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (35,'Michigan Legal Help','LEGAL_AID','Free self-help legal information and guided interviews for Michigan residents. Covers: divorce, eviction, expungement, benefits, and more. Visit michiganlegalhelp.org. Also connects to local legal aid.','MI',NULL,NULL,'https://michiganlegalhelp.org',NULL,NULL,1,NULL,'["English"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
  (36,'Northwest Justice Project','LEGAL_AID','Largest provider of free civil legal services in Washington State. Covers all 39 counties. Call CLEAR statewide intake: 888-201-1014.','WA',NULL,'888-201-1014','https://nwjustice.org',NULL,'Mon-Fri 9:15am-12:15pm',1,'200% FPL','["English", "Spanish"]',1,'resource',0,NULL,NULL,NULL,NULL,NULL,NULL),
